mapper.select:
SELECT
    ${timeExpression} AS log_timestamp,
    toString(${messageExpression}) AS message,
    toString(${rawExpression}) AS raw,
    toString(${sourceIpExpression}) AS source_ip,
    toString(${hostnameExpression}) AS hostname,
    toString(${severityExpression}) AS severity
FROM ${tableExpression}
WHERE 1 = 1

    AND ${timeExpression} > #{startTime}


    AND ${timeExpression} <= #{endTime}

ORDER BY ${timeExpression} ASC
LIMIT #{limit}
